-- Clyde May's (clydemays.com) import, 2026-10-11. Producer stays Conecuh Ridge (maker 1b0c0fea...). Applied: part1 then inserts_1.
update cellar.products set age_years = 4.0, age_label = '4 yr', nas = false, specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://clydemays.com/wp-content/uploads/2025/06/Clyde-Mays-Straight-Rye-Whiskey-750x1500px-optimized.png'), producer = coalesce(producer, 'Conecuh Ridge'), producer_id = coalesce(producer_id, '1b0c0fea-12a0-48e8-ae95-b8e16ec24c39'::uuid), source = 'maker', source_url = 'https://clydemays.com/straight-rye-whiskey/', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range where id = '095b12eb-a8d0-4a7a-959a-e0e176d8fe67' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('3aa35a48-4954-421e-8127-86b821cc8e17', '095b12eb-a8d0-4a7a-959a-e0e176d8fe67');
update cellar.products set source = 'maker', source_url = 'https://clydemays.com/straight-bourbon-whiskey/', discontinued = false, catalog_included = catalog_included or is_core_range, producer = coalesce(producer, 'Conecuh Ridge'), producer_id = coalesce(producer_id, '1b0c0fea-12a0-48e8-ae95-b8e16ec24c39'::uuid), specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://clydemays.com/wp-content/uploads/2025/06/Clyde-Mays-Straight-Bourbon-Whiskey-750x1500px-b-optimized.png') where id = '3aa35a48-4954-421e-8127-86b821cc8e17' and facts_verified_at is null;
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Clyde May's Special Reserve","rar":"shelf","f":"Clyde May's","x":"Special Reserve","p":110.0,"ay":6.0,"al":"6 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Clyde May's Special Reserve Bourbon","Clyde May's Special Reserve Straight Bourbon"],"img":"https://clydemays.com/wp-content/uploads/2025/06/Clyde-Mays-Special-Reserve-Bourbon-Whiskey-750x1500px-optimized.png","u":"https://clydemays.com/special-reserve-bourbon/","pr":"Conecuh Ridge","mk":"1b0c0fea-12a0-48e8-ae95-b8e16ec24c39"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');